import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"抑","description":"","frontmatter":{"title":"抑","date":"2026-11-09T00:00:00.000Z","seq":22,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/抑.md","filePath":"blogs/诗经·大雅/抑.md"}'),o={name:"blogs/诗经·大雅/抑.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="抑" tabindex="-1">抑 <a class="header-anchor" href="#抑" aria-label="Permalink to &quot;抑&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　荡之什</p><div class="poem"><p class="poem-stanza">抑抑威仪，维德之隅。人亦有言：靡哲不愚，庶人之愚，亦职维疾。</p><p class="poem-stanza">哲人之愚，亦维斯戾。无竞维人，四方其训之。有觉德行，四国顺之。</p><p class="poem-stanza">訏谟定命，远犹辰告。敬慎威仪，维民之则。其在于今，兴迷乱于政。</p><p class="poem-stanza">颠覆厥德，荒湛于酒。女虽湛乐从，弗念厥绍。罔敷求先王，克共明刑。</p><p class="poem-stanza">四皇天弗尚，如彼泉流，无沦胥以亡。夙兴夜寐，洒扫庭内，维民之章。</p><p class="poem-stanza">修尔车马，弓矢戎兵，用戒戎作，用逷蛮方。质尔人民，谨尔侯度，用戒不虞。</p><p class="poem-stanza">慎尔出话，敬尔威仪，无不柔嘉。白圭之玷，尚可磨也；斯言之玷，不可为也！</p><p class="poem-stanza">无易由言，无曰苟矣，莫扪朕舌，言不可逝矣。无言不仇，无德不报。</p><p class="poem-stanza">惠于朋友，庶民小子。子孙绳绳，万民靡不承。视尔友君子，辑柔尔颜，不遐有愆。</p><p class="poem-stanza">相在尔室，尚不愧于屋漏。无曰不显，莫予云觏。神之格思，不可度思，矧可射思！</p><p class="poem-stanza">辟尔为德，俾臧俾嘉。淑慎尔止，不愆于仪。不僭不贼，鲜不为则。投我以桃，报之以李。</p><p class="poem-stanza">彼童而角，实虹小子。荏染柔木，言缗之丝。温温恭人，维德之基。</p><p class="poem-stanza">其维哲人，告之话言，顺德之行。其维愚人，覆谓我僭。民各有心。</p><p class="poem-stanza">于乎小子，未知臧否。匪手携之，言示之事。匪面命之，言提其耳。</p><p class="poem-stanza">借曰未知，亦既抱子。民之靡盈，谁夙知而莫成？昊天孔昭，我生靡乐。</p><p class="poem-stanza">视尔梦梦，我心惨惨。诲尔谆谆，听我藐藐。匪用为教，覆用为虐。</p><p class="poem-stanza">借曰未知，亦聿既耄。于乎，小子，告尔旧止。听用我谋，庶无大悔。</p><p class="poem-stanza">天方艰难，曰丧厥国。取譬不远，昊天不忒。回遹其德，俾民大棘。</p></div>',3)])])}const d=s(o,[["render",c]]);export{z as __pageData,d as default};
